    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check attributes that typically contain URLs or sources
    attr.name in {"url", "source", "baseurl", "mirrorlist"}

    # Check if the value is a string or a complex expression containing a string
    is_insecure_url(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Integrity Check - Insecure protocol used in data transmission (CWE-353)"
    }
}

